#!/usr/bin/env python3
"""Generate a review-gated, structurally complete portable YT-SQL case draft."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
import tempfile
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
SQL_ROOT = PROJECT / "yt-sql"
sys.path.insert(0, str(SQL_ROOT))

from run_python_candidate import observe  # noqa: E402

WARNING = (
    "UNVERIFIED: This expectation was generated by the Python implementation. "
    "Python may contain defects. Independently review syntax, values, types, NULLs and diagnostics before "
    "admitting the case to the normative corpus."
)
ID_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*(?:\.[a-z][a-z0-9_-]*)+$")


def datasets(root: Path = SQL_ROOT) -> dict[str, str]:
    """Discover valid fixture identifiers from the engine's committed dataset directory."""
    found = {}
    for path in sorted((root / "datasets").glob("*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if data.get("kind") in {"static", "source-topology", "facet-topology"} and isinstance(
            data.get("records"), list
        ):
            found[path.stem] = data["kind"]
    return found


def draft(
    query: Path,
    destination: Path,
    *,
    case_id: str,
    dataset: str,
    order: str,
    description: str = "Unverified Python-generated candidate",
    features: tuple[str, ...] = (),
) -> None:
    """Write an immediately inspectable draft without granting normative authority."""
    if not query.is_file() or query.suffix != ".ysql":
        raise ValueError("input must be an existing .ysql file")
    if not ID_PATTERN.fullmatch(case_id):
        raise ValueError("case ID must contain dot-separated lowercase ASCII identifiers")
    if order not in {"ordered", "unordered"}:
        raise ValueError("unsupported ordering mode")
    available = datasets()
    if dataset not in available:
        raise ValueError(f"unknown or unsupported dataset {dataset!r}; use --list-datasets")
    if any(not ID_PATTERN.fullmatch(feature) for feature in features):
        raise ValueError("features must use dot-separated lowercase identifiers")
    if destination.exists() or destination.is_symlink():
        raise FileExistsError(f"destination already exists: {destination}")
    if destination.resolve().is_relative_to((SQL_ROOT / "cases").resolve()):
        raise ValueError("unreviewed candidates must be written outside the normative cases directory")
    source = query.read_bytes()
    with tempfile.TemporaryDirectory(prefix="ytsql-candidate-") as temporary:
        case = Path(temporary)
        (case / "query.ysql").write_bytes(source)
        manifest = {
            "version": 1,
            "id": case_id,
            "description": description,
            "datasets": [dataset],
            "query": "query.ysql",
            "expected": "expected.json",
            "order": order,
        }
        if features:
            manifest["features"] = list(features)
        (case / "test.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        result = observe(case, root=SQL_ROOT)
        review = {
            "version": 1,
            "status": "unverified",
            "reference_implementation": "python",
            "source_sha256": hashlib.sha256(source).hexdigest(),
            "warning": WARNING,
            "review_required": [
                "syntax and intent",
                "result values and column order",
                "types and coercions",
                "NULL and boundary behaviour",
                "error classification",
            ],
        }
        destination.mkdir(parents=True, exist_ok=False)
        for name in ("query.ysql", "test.json"):
            (destination / name).write_bytes((case / name).read_bytes())
        (destination / "expected.json").write_text(
            json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
        )
        (destination / "REVIEW.json").write_text(
            json.dumps(review, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
        )
    target = SQL_ROOT / "cases" / Path(*case_id.split("."))
    print(WARNING, file=sys.stderr)
    print(f"Draft: {destination}")
    print(f"After independent review, add query.ysql, test.json and expected.json to: {target}")
    print(f"Manifest entry: {target / 'test.json'} (already generated; id={case_id}, datasets=[{dataset}])")
    print("Do not copy REVIEW.json into the normative corpus. No central case manifest edit is required:")
    print("the conformance runner discovers case directories through their test.json manifests.")
    print("Validate after review: python yt-sql/validate_corpus.py")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, epilog=WARNING)
    parser.add_argument("query", nargs="?", type=Path, help="Existing YT-SQL .ysql query")
    parser.add_argument("destination", nargs="?", type=Path, help="New draft directory outside yt-sql/cases")
    parser.add_argument("--id", help="Proposed normative case ID, e.g. scalar.lower_unicode")
    parser.add_argument("--dataset", default="python-v6-small", help="Portable fixture ID (see --list-datasets)")
    parser.add_argument("--list-datasets", action="store_true", help="List supported committed engine datasets")
    parser.add_argument("--description", default="Unverified Python-generated candidate")
    parser.add_argument("--feature", action="append", default=[], help="Declared language feature; repeatable")
    parser.add_argument("--order", choices=("ordered", "unordered"), default="ordered")
    args = parser.parse_args()
    if args.list_datasets:
        for name, kind in datasets().items():
            print(f"{name}\t{kind}")
        return 0
    if args.query is None or args.destination is None or args.id is None:
        parser.error("query, destination and --id are required unless --list-datasets is used")
    try:
        draft(
            args.query,
            args.destination,
            case_id=args.id,
            dataset=args.dataset,
            order=args.order,
            description=args.description,
            features=tuple(args.feature),
        )
    except (OSError, ValueError, RuntimeError, KeyError, TypeError) as exc:
        print(f"Cannot generate candidate: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
